// Üretilen dosya: tool/ozgun/uret.py. Doğa · Genel ek sorular: Doğa kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Hayvanlar: davranış, yaşam alanı, sınıflandırma | Bitkiler ve ormanlar; Türkiye'nin endemik türleri | Ekoloji, ekosistemler ve çevre sorunları | Doğa olayları, okyanuslar, mağaralar ve millî parklar) (zor).
const ozNature5Zor = <(String, String, List<String>, String)>[
  ('Kırkayaklar (Diplopoda) ile çıyanları (Chilopoda) ayırt etmeye yarayan özellik hangisidir?', 'Kırkayakta halka başına iki çift, çıyanda bir çift bacak olması', ['Kırkayağın sekiz, çıyanın altı bacağının olması', 'Kırkayağın kanatlı, çıyanın kanatsız olması', 'Kırkayağın akciğerle, çıyanın ise solungaçla solunum yapması'], 'Kırkayakların gövde halkalarının çoğunda iki çift bacak bulunur ve genellikle ölü bitkilerle beslenirler; çıyanlarda her halkada bir çift bacak ve zehirli çeneler vardır.'),
  ('Böceklerin dolaşım sisteminin omurgalılarınkinden temel farkı hangisidir?', 'Kanın organlar arasındaki boşluklarda dolaşması', ['Kalbin dört odacıklı olması ve kanın yalnız atardamarlarda akması', 'Kanın akciğerlerde oksijenlenmesi', 'Kırmızı kan hücrelerinin çekirdeksiz ve çok küçük olması'], 'Böceklerde hemolenf denen sıvı vücut boşluğunda organların arasını doldurarak dolaşır; oksijen taşıma işini büyük ölçüde trake sistemi üstlendiği için kan bu işte önemsizdir.'),
  ('Sineklerin (iki kanatlılar) uçuşta dengesini sağlayan ve arka kanatlardan dönüşmüş küçük topuz biçimli yapılara ne ad verilir?', 'Denge topuzu (halter)', ['Anten sapı', 'Göz kapağı', 'Ön kanat zarı (elitra)'], 'İki kanatlılarda arka kanat çifti, hızla titreşen ve jiroskop gibi dönüşleri algılayan küçük denge topuzlarına dönüşmüştür.'),
  ('Akdeniz\'e özgü, boyu bir metreyi aşabilen ve deniz çayırları arasında dik duran büyük çift kabuklu yumuşakça hangisidir?', 'Pina (Pinna nobilis)', ['Dev istiridye (Crassostrea)', 'Akivades', 'Kum midyesi'], 'Pina, Akdeniz\'in en büyük çift kabuklularından biridir; 2016\'dan bu yana bir parazitin yol açtığı toplu ölümler nedeniyle nesli kritik tehlike altındadır.'),
  ('Deniz kestanelerinin alg kazımak için kullandığı beş dişli karmaşık çene aparatına ne ad verilir?', 'Aristoteles feneri', ['Radula', 'Sifon', 'Ambulakral kanal'], 'Deniz kestanesinin ağzında beş sivri dişten ve bunları hareket ettiren kaslardan oluşan bir aparat bulunur; Aristoteles bunu fenere benzettiği için bu adla anılır.'),
  ('Gelgit düzlüklerinde yaşayan çamur zıplayanları (Periophthalmus) uzun süre suyun dışında nasıl kalabilir?', 'Nemli deri ve ağız boşluğuyla oksijen alıp yüzgeçleriyle sürünürler', ['Vücutlarındaki yağı yakarak oksijene gerek duymazlar', 'Kabuklu bir yumurta içine girip kurumaktan korunurlar', 'Yalnız gece çıkıp solungaçlarıyla havadaki nemi süzerek oksijen sağlarlar'], 'Çamur zıplayanları derileri ve ağız-yutak zarlarıyla havadan oksijen alır; solungaç odalarında su tutar, kaslı göğüs yüzgeçleriyle yürür ve zıplarlar.'),
  ('Akdeniz\'in kayalık diplerinde yaşayan orfozların (Epinephelus marginatus) üreme biyolojisi hakkında hangisi doğrudur?', 'Önce dişi olarak olgunlaşır, ileri yaşta erkeğe dönüşürler', ['Bütün bireyler yaşamları boyunca erkek kalır', 'Yalnız tatlı sulara girerek ürer, denizde hiç yumurtlamazlar', 'Döllenme dişinin ağzında gerçekleşir ve yavrular orada büyür'], 'Orfoz dişi olarak başlayıp erkeğe dönüşen (protogin) bir türdür. Büyük bireylerin avlanması erkekleri azalttığı için tür aşırı avcılığa karşı özellikle duyarlıdır.'),
  ('Türkiye\'de yaz göçmeni olan renkli arıkuşları (Merops apiaster) yuvalarını genellikle nereye yapar?', 'Akarsu kıyısındaki toprak yarlara kazdıkları tünellere', ['Yüksek kayalıklarda dallardan yaptıkları büyük platformlara', 'Sazlıkların arasına örülmüş yüzen yuvalara', 'Başka kuşların terk ettiği ağaç kovuklarına'], 'Arıkuşları koloniler hâlinde dik toprak yarlara bir iki metre uzunluğunda tüneller kazar ve yumurtalarını tünelin sonundaki odacığa bırakır.'),
  ('Bir dişi kanguru kesesinde emzirdiği yavru varken yeniden çiftleşirse yeni embriyo çoğunlukla ne olur?', 'Gelişmesi durdurulup kese boşalana dek bekletilir', ['Hemen gelişip kesedeki yavruyla aynı anda doğar', 'Annenin vücudu tarafından hemen yok edilir', 'Kesedeki yavrunun yerine geçmek için onu keseden dışarı iter'], 'Kangurularda embriyonik diyapoz görülür: embriyo erken evrede bekler, keseden yavru ayrılınca gelişmesini sürdürür. Böylece üreme koşullara göre ayarlanır.'),
  ('Güney Amerika\'daki zehir oku kurbağaları esaret altında yapay besinlerle büyütüldüğünde genellikle zehirsiz olur. Bunun en olası açıklaması nedir?', 'Zehirlerini doğada yedikleri karınca ve akarlardan sağlarlar', ['Zehri yalnız tropikal sıcaklıkta derideki bakteriler üretebilir', 'Zehir yalnız yağmurlu mevsimde ve yüksek nemde üretilebilir', 'Zehri yalnız erkekler çiftleşme döneminde üretir'], 'Bu kurbağaların deri alkaloitleri büyük ölçüde besinlerinden gelir; doğal besinlerinden yoksun bırakılan bireyler zehir biriktiremez.'),
  ('Türkiye\'nin Teke Yarımadası ve çevresindeki kireçtaşı kayalıklarına özgü, her türü çok dar bir alanda yaşayan ve canlı yavru doğuran semender cinsi hangisidir?', 'Likya semenderi (Lyciasalamandra)', ['Ateş semenderi (Salamandra infraimmaculata)', 'Aksolotl (Ambystoma)', 'Dev semender (Andrias)'], 'Lyciasalamandra türleri Batı Akdeniz\'in kireçtaşı alanlarına özgüdür; her biri dar bir bölgede yaşar ve endemik olarak korunur.'),
  ('Mersin\'in Silifke ilçesinde bulunan Göksu Deltası, Türkiye\'de hangi kuş türünün en önemli yaşam alanı olarak bilinir?', 'Mor sultan tavuğu', ['Kelaynak', 'Toy', 'Kızıl akbaba'], 'Göksu Deltası\'nın sazlıkları, mor-mavi tüylü ve kırmızı gagalı mor sultan tavuğunun Türkiye\'deki başlıca üreme alanıdır.'),
  ('Burdur Gölü kışın hangi küresel ölçekte nesli tehlike altındaki dalıcı ördeğin dünyadaki en önemli kışlama alanlarından biri olarak bilinir?', 'Dikkuyruk', ['Yeşilbaş', 'Tepeli pelikan', 'Angıt'], 'Mavi gagalı, dik kuyruklu dikkuyruk ördeği (Oxyura leucocephala) kışın Burdur Gölü\'nde binlerle toplanır; gölün sularının azalması bu tür için ciddi tehdittir.'),
  ('Türkiye sulak alanları korumaya yönelik Ramsar Sözleşmesi\'ne hangi yıl taraf olmuştur?', '1994 yılında', ['1971 yılında', '1982 yılında', '2004 yılından sonra'], 'Türkiye Ramsar Sözleşmesi\'ni 1994\'te onaylamış ve aynı yıl ilk sulak alanlarını uluslararası listeye eklemiştir. Sözleşme ise 1971\'de imzaya açılmıştır.'),
  ('Karadeniz\'de \'taflan\' adıyla da bilinen, parlak deri gibi yapraklı herdem yeşil ve olgunlaşınca siyahlaşan meyveli bitki hangisidir?', 'Karayemiş (Prunus laurocerasus)', ['Kocayemiş (Arbutus unedo)', 'Mersin (Myrtus communis)', 'Mor çiçekli ormangülü (Rhododendron)'], 'Karayemiş Karadeniz kıyı ormanlarında yaygındır; olgun meyvesi yenir ama yaprakları ve çekirdekleri siyanür açığa çıkaran bileşikler içerdiğinden zehirlidir.'),
  ('Güneydoğu Anadolu\'da kavrulmuş meyvesinden geleneksel bir kahve yapılan menengiç (Pistacia terebinthus), Antep fıstığı yetiştiriciliğinde hangi amaçla da kullanılır?', 'Üzerine Antep fıstığı aşılanan anaç olarak', ['Fıstık ağaçlarını rüzgârdan koruyan çit olarak', 'Fıstık meyvelerini boyamak için', 'Fıstık bahçelerinde toprak örtüsü olarak'], 'Menengiç kurağa ve kireçli toprağa dayanıklı bir yabani Pistacia türüdür; doğal menengiç ağaçlarına Antep fıstığı aşılanarak verimli bahçeler kurulur.'),
  ('Titrek kavağın (Populus tremula) yapraklarının çok hafif bir esintide bile titreşmesinin nedeni nedir?', 'Yaprak sapının yanlardan basık, yassı olması', ['Yaprakların içinin hava dolu olması', 'Yaprak kenarlarının dikenli olması', 'Yaprakların gövdeye sapsız ve doğrudan bağlanmış olması'], 'Yassı yaprak sapı bir yöne kolayca bükülür; bu yüzden yaprak ayası rüzgârda sağa sola sallanır ve ağaç sürekli hışırdar.'),
  ('Artvin ve Doğu Karadeniz ladin ormanlarında ağaçlara zarar veren dev ladin kabuk böceğine karşı uygulanan biyolojik mücadele yöntemi hangisidir?', 'Larvaları yiyen avcı bir böceğin üretilip salınması', ['Ormandaki bütün ladin ağaçlarının kesilip yakılarak yerine fidan dikilmesi', 'Ormanın uçaklardan sürekli ilaçlanması', 'Ladin yerine kavak dikilmesi'], 'Dev ladin kabuk böceğiyle (Dendroctonus micans) mücadelede, larvalarıyla beslenen Rhizophagus grandis adlı avcı böcek laboratuvarda üretilip ormana bırakılmıştır.'),
  ('Kırmızı mangrov ağaçlarında tohumun ana ağaçtan düşmeden önce filizlenip uzun bir fide hâline gelmesinin gelgit ortamında sağladığı yarar nedir?', 'Düşen fidenin çamura saplanıp hızla kök salması', ['Tohumun tuzlu suyla hiç temas etmemesi', 'Fidelerin kuşlar tarafından yutulup uzak adalara taşınması', 'Ağacın her yıl daha az tohum üretmesi'], 'Mangrovlarda görülen bu vivipari sayesinde fide gelgit suyu çekildiğinde çamura dikine saplanır ya da suyla sürüklenip uygun yerde hızla tutunur.'),
  ('Tırtıllar tarafından yenen bazı bitkilerin havaya özel uçucu kimyasallar salması hangi sonucu doğurabilir?', 'Tırtılları avlayan parazit eşek arılarının çekilmesi', ['Tırtılların hemen kelebeğe dönüşmesi', 'Bitkinin bütün yapraklarını aynı gün dökmesi', 'Yağmur bulutlarının bitkinin üstünde toplanması'], 'Zarar gören yapraklardan yayılan kokular, tırtılların içine yumurta bırakan parazitoit eşek arıları için bir işarettir; böylece bitki dolaylı yoldan savunma yapar.'),
  ('Amerika\'daki avize çiçeği (Yucca) ile yucca güvesi arasındaki ilişki neden ekoloji kitaplarında özel bir örnek olarak anlatılır?', 'Güve çiçeği tozlaştırır, larvaları tohumların bir kısmını yer', ['Güve yalnız yaprakları yiyip bitkiyi kurutan bir zararlıdır', 'Bitki güveyi yapışkan tüylerle yakalayıp sindirir', 'Güve bitkinin köklerinde kış uykusuna yatar'], 'Dişi yucca güvesi poleni toplayıp başka bir çiçeğin dişi organına bastırır ve yumurtasını oraya bırakır; iki tür birbirine zorunlu olarak bağımlıdır.'),
  ('Domates ve patlıcan gibi bitkilerin polenini en iyi bombus arılarının (yaban arısı) bırakmasının nedeni nedir?', 'Çiçeğe tutunup kas titreşimiyle poleni silkelemeleri', ['Çiçeğin içine girip tüm nektarı tüketmeleri', 'Poleni ağızlarında toplayıp ezmeleri', 'Yalnız gece uçarak serin saatlerde çalışmaları'], 'Bu bitkilerin başçıkları poleni küçük deliklerden bırakır; bombus arıları uçuş kaslarını belli bir frekansta titreterek poleni dışarı sallar. Bu nedenle seralarda bombus kolonileri kullanılır.'),
  ('ABD\'nin Oregon eyaletindeki bir ormanda yaklaşık 9 kilometrekarelik alana yayılan ve dünyanın en büyük canlılarından biri sayılan organizma hangisidir?', 'Bir bal mantarının (Armillaria) miselyumu', ['Tek bir dev sekoya ağacının yer altındaki kök sistemi', 'Bir karınca kolonisinin yer altı tünelleri', 'Bir kavak korusunun ortak gövdesi'], 'Armillaria ostoyae türünün genetik olarak tek bir bireyi, ağaç köklerine yayılan miselyumuyla geniş bir orman alanını kaplar ve binlerce yıllık olduğu tahmin edilir.'),
  ('20. yüzyılın başında Asya\'dan taşınan bir mantar hastalığının Kuzey Amerika ormanlarında yol açtığı büyük ekolojik kayıp hangisidir?', 'Amerikan kestanesinin neredeyse tamamen yok olması', ['Kuzey Amerika\'daki bütün meşelerin kuruması', 'Sekoyaların yarısının köklerinden çürüyüp devrilmesi', 'Akçaağaçların kırmızı yaprak rengini kaybetmesi'], 'Kestane dal kanseri (Cryphonectria parasitica) birkaç on yılda milyarlarca Amerikan kestanesini öldürdü; tür bugün çoğunlukla kökten süren cılız filizler hâlinde yaşar.'),
  ('Bir kuş türü verimli bir ormanda bol yavru yetiştirirken yakındaki bozulmuş bir parkta ürediği hâlde ölümler doğumlardan fazladır; parktaki popülasyon yalnız ormandan gelen göçmenlerle sürmektedir. Park için hangi tanım uygundur?', 'Havuz (batak) popülasyonu', ['Kaynak popülasyonu', 'Kalıntı (relikt) popülasyonu', 'Kurucu popülasyonu'], 'Kaynak-havuz modelinde kaynak alanlar fazla birey üretir; havuz alanlarda ise yerel üreme yetmez ve popülasyon dışarıdan gelen göçle ayakta kalır.'),
  ('Güney Afrika\'nın güneybatı ucunda yer alan ve dar alanında binlerce endemik bitki türü barındıran Akdeniz tipi çalılık bitki örtüsüne ne ad verilir?', 'Fynbos', ['Pampa', 'Llanos çayırı', 'Taiga'], 'Fynbos, Kap Floristik Bölgesi\'nin sert yapraklı çalılığıdır; çok sayıda funda ve protea türü içerir ve yangınlar bu ekosistemin doğal bir parçasıdır.'),
  ('Sığ göllerin bazıları su altı bitkileriyle kaplı ve berrak, bazıları ise yoğun alg nedeniyle bulanık hâlde uzun süre kalır. Berrak durumu sürdüren başlıca etken hangisidir?', 'Su altı bitkilerinin tortuyu ve besin tuzlarını tutması', ['Göl yüzeyinin yılın büyük bölümünde kalın bir buzla örtülü olması', 'Gölde hiç balık ve zooplankton bulunmaması', 'Gölün suyunun her gün tamamen yenilenmesi'], 'Köklü su bitkileri tortuyu sabitler, besin tuzlarını tüketir ve alg yiyen zooplanktona sığınak sağlar. Fazla besin girdisi bu dengeyi bozunca göl bulanık alg baskın duruma geçebilir.'),
  ('Bir maden ocağından çıkan kayaçlardaki pirit (demir sülfür) hava ve suyla temas ettiğinde yakındaki derenin suyu turuncuya döner ve asitlenir. Bu soruna ne ad verilir?', 'Asit maden drenajı', ['Kentsel ısı adası etkisi', 'Ötrofikasyon', 'Tuzlanma'], 'Pirit oksitlenince sülfürik asit ve çözünmüş demir oluşur; asitli su ağır metalleri de çözerek derelerdeki yaşamı ciddi biçimde zarar görür.'),
  ('1950\'lerde Afrika\'daki Viktorya Gölü\'ne balıkçılığı geliştirmek için bırakılan iri yırtıcı balığın en ağır ekolojik sonucu ne olmuştur?', 'Göle özgü çiklit türlerinin büyük kısmının yok olması', ['Gölün sularının tamamen çekilip bir tuz çölüne dönüşmesi', 'Göldeki timsahların tümünün başka göllere göç etmesi', 'Göl çevresindeki ormanların yangınla yok olması'], 'Nil levreği gölün endemik çiklit balıklarını avlayarak çok sayıda türün tükenmesine yol açtı; bu olay istilacı türlerin yerli faunayı nasıl çökertebileceğinin ders kitabı örneğidir.'),
  ('Çin kökenli olup Türkiye\'de yol kenarlarında, demiryolu şevlerinde ve boş arsalarda hızla yayılan, köklerinden yeni sürgünler veren ve yapraklarından kötü koku yayan istilacı ağaç hangisidir?', 'Kokarağaç (Ailanthus altissima)', ['Akçaağaç (Acer campestre)', 'Karaağaç (Ulmus minor subsp. canescens)', 'Dişbudak (Fraxinus excelsior)'], 'Kokarağaç kurak ve kirli koşullara dayanıklıdır, bol tohum verir ve çevresindeki bitkilerin büyümesini engelleyen maddeler salgılar; bu yüzden sökülmesi çok zordur.'),
  ('İngiltere\'de Kuzey Amerika\'dan getirilen gri sincabın yayılmasıyla yerli kızıl sincabın birçok bölgeden çekilmesinin iki temel nedeni hangisidir?', 'Üstün besin rekabeti ve taşıdığı ölümcül bir virüs', ['Kızıl sincapları doğrudan avlayıp yemesi ve yuvalarını yakması', 'Ormanları kesip yerine çayır oluşturması', 'Kızıl sincaplarla çiftleşip kısır melezler üretmesi'], 'Gri sincaplar meşe palamutlarını daha iyi sindirir ve kendilerini hasta etmeyen sincap çiçek virüsünü kızıl sincaplara bulaştırır; iki etki birleşince yerli tür hızla geriler.'),
  ('Kurak bölgelerde sürekli aynı yönden esen rüzgârın yumuşak kayaçları oyarak oluşturduğu, rüzgâr yönünde uzanan ters çevrilmiş tekne biçimli sırtlara ne ad verilir?', 'Yardang', ['Barkan', 'Tombolo', 'Drumlin'], 'Yardanglar rüzgâr aşındırmasının ürünüdür ve uzun eksenleri rüzgâr yönüne paraleldir; Mısır ve İran çöllerinde çok sayıda örneği bulunur.'),
  ('Bir buzul eridikten sonra geride kalan, buzulun akış yönünde uzanmış, ters kaşık ya da yumurta biçimli küçük tepelere ne ad verilir?', 'Drumlin', ['Esker', 'Sirk', 'Fiyort'], 'Drumlinler buzulun altında sıkışan moloz ve kilin buzun hareketiyle biçimlenmesinden oluşur; dik ucu buzulun geldiği yönü, sivri ucu gittiği yönü gösterir.'),
  ('Buzulun altındaki tünellerde akan erime sularının bıraktığı kum ve çakıllardan oluşan, kilometrelerce uzanabilen dar ve kıvrımlı sırtlara ne ad verilir?', 'Esker', ['Drumlin', 'Moren', 'Lapya'], 'Eskerler buzul altı akarsularının yataklarında biriken tortuların, buz eridikten sonra açıkta kalmasıyla ortaya çıkar ve eski akarsuyun kıvrımlarını korur.'),
  ('Granit gibi kayaçların yüzeyinde tuz kristallenmesi ve nem etkisiyle oluşan, birbirine bitişik bal peteği ya da oyuk biçimli küçük çukurlara ne ad verilir?', 'Tafoni (petek aşınması)', ['Dolin', 'Lapya', 'Polye (karstik ova)'], 'Tafoniler özellikle kıyılarda ve kurak bölgelerde, kayaç gözeneklerinde kristalleşen tuzların taneleri koparmasıyla gelişir; Korsika ve Akdeniz kıyılarında sık görülür.'),
  ('Anadolu\'nun kapalı havzalarındaki göl, kaynak ve sazlıklarda çok sayıda endemik türü bulunan, birkaç santimetre boyundaki dişli küçük balık cinsi hangisidir?', 'Dişli sazancık (Aphanius)', ['Alabalık (Salmo)', 'Sazan (Cyprinus)', 'Turna balığı (Esox lucius)'], 'Aphanius türleri tuzlu ve sıcak kaynak sularına kadar zor koşullara dayanabilir; birbirinden yalıtılmış havzalarda ayrı türlere ayrıldıkları için birçoğu Türkiye\'ye endemiktir ve su çekimi nedeniyle tehlikededir.'),
  ('Türkiye\'de alageyiğin (Dama dama) doğal olarak yaşamını sürdüren son popülasyonu hangi koruma alanında bulunur?', 'Antalya Düzlerçamı Yaban Hayatı Geliştirme Sahası', ['Bolu Yedigöller Millî Parkı', 'Kars Kuyucuk Gölü', 'Artvin Karagöl-Sahara Millî Parkı'], 'Alageyik bir zamanlar Anadolu\'da yaygındı; aşırı avcılık ve yaşam alanı kaybıyla Antalya\'daki Düzlerçamı çevresinde küçük bir doğal topluluk kalmıştır. Buradan alınan bireylerle başka alanlara yeniden yerleştirme yapılmaktadır.'),
  ('Bazı renkli deniz salyangozlarının (nudibranşlar) yedikleri denizanası ve şakayıkların yakıcı hücrelerini sindirmeden kendi vücutlarına yerleştirmesi onlara ne sağlar?', 'Çaldıkları bu hücrelerle avcılara karşı kendilerini savunmak', ['Bu hücrelerle fotosentez yapıp besin üretmek', 'Bu hücreleri yumurtalarına besin olarak vermek', 'Bu hücrelerle suyun tuzluluğunu ölçmek'], 'Bazı nudibranşlar avlarının patlamamış knidositlerini sırt çıkıntılarına taşır; avcı onları ısırınca bu hücreler ateşlenir. Parlak renkleri de bu tehlikeyi duyurur.'),
  ('Slovenya ve Hırvatistan\'ın karstik mağaralarındaki yer altı sularında yaşayan, gözleri derinin altında kalmış, pembemsi beyaz ve yüz yılı aşkın yaşayabilen semender hangisidir?', 'Olm (Proteus anguinus)', ['Aksolotl (Ambystoma mexicanum)', 'Dev semender (Andrias japonicus)', 'Ateş semenderi (Salamandra salamandra)'], 'Olm, Dinar Alpleri\'nin yer altı sularına uyum sağlamış bir mağara semenderidir; çok yavaş metabolizması sayesinde yıllarca beslenmeden yaşayabilir.'),
  ('Madagaskar\'da yaşayan aye-aye adlı lemurun ağaç gövdesindeki böcek larvalarını bulma yöntemi nasıldır?', 'Gövdeye vurup yankıyı dinler, ince uzun orta parmağıyla larvayı çıkarır', ['Gövdeyi koklayıp dişleriyle bütün ağacı devirir', 'Yapışkan diliyle kabuğun üstündeki karıncaları toplar', 'Gövdeye su püskürterek larvaları dışarı çıkmaya zorlar'], 'Aye-aye ağaçkakanın Madagaskar\'daki işlevini üstlenir: parmağıyla vurarak boşlukları bulur, keskin dişleriyle oyuk açar ve iskelet gibi ince parmağıyla larvayı çeker.'),
  ('Asya\'da yaşayan yavaş lorislerin primatlar arasında benzersiz sayılan savunma özelliği hangisidir?', 'Kol bezlerinin salgısını tükürükle karıştırıp zehirli ısırık oluşturmaları', ['Tehlikede derilerinden elektrik vermeleri', 'Kuyruklarını koparıp kaçmaları', 'Gece parlayan kürkleriyle avcıları korkutmaları'], 'Yavaş lorisler bilinen tek zehirli primatlardır; dirsek yakınındaki kol bezlerinin salgısını yalayıp tükürükle karıştırarak ısırıklarını acı verici ve tehlikeli hâle getirirler.'),
  ('Tazmanya canavarı (Tasmanian devil) popülasyonunu 1990\'lardan bu yana ciddi biçimde azaltan hastalığın olağan dışı özelliği nedir?', 'Isırma yoluyla bireyden bireye bulaşan bir kanser olması', ['Yalnız sivrisineklerle taşınan bir virüs olması', 'Yalnız erkekleri etkileyen kalıtsal bir kas hastalığı olması', 'Kirli sulardan bulaşan bir bağırsak paraziti olması'], 'Tazmanya canavarı yüz tümörü hastalığında kanser hücrelerinin kendisi kavga sırasında ısırıkla başka bireye geçer; türün düşük genetik çeşitliliği bu yayılmayı kolaylaştırır.'),
  ('At nalı yengeçlerinin (Limulus) mavi renkli kanı tıpta hangi amaçla değerlidir?', 'İlaç ve tıbbi gereçlerde bakteri kaynaklı zehirleri saptayan testin yapımında', ['Kan bağışlarında insan kanının yerine kullanılmasında', 'Kemik kırıklarını yapıştıran bir tutkal üretiminde', 'Göz hastalıklarında yapay mercek yapımında'], 'At nalı yengecinin kan hücrelerinden elde edilen madde bakteriyel endotoksinlerle temas edince pıhtılaşır; aşılar ve enjeksiyonlar bu testle denetlenir. Yengeçler kanları alındıktan sonra denize bırakılır.'),
  ('Bazı bok böceklerinin aysız gecelerde bile yuvarladıkları dışkı topunu düz bir çizgide götürebilmesi deneylerde neye bağlanmıştır?', 'Samanyolu\'nun gökyüzündeki parlak şeridini yön işareti olarak kullanmalarına', ['Toprağın sıcaklığını ayaklarıyla ölçmelerine', 'Rüzgârın yönünü antenleriyle algılamalarına', 'Dışkı topunun kokusunun hep kuzeye doğru yayılmasına'], 'Güney Afrika\'da yapılan planetaryum deneylerinde, gökyüzündeki Samanyolu görüntüsü kapatılınca böceklerin düz gidemediği, görünür olunca yolunu koruduğu gösterilmiştir.'),
  ('Bazı bambu türlerinin onlarca yılda bir geniş bir bölgede aynı anda çiçeklenip ölmesinin ardından Hindistan\'ın kuzeydoğusunda zaman zaman görülen ekolojik olay hangisidir?', 'Bol tohumla beslenen sıçanların patlama yapıp tarlaları yağmalaması', ['Ormanda aniden kaplan sayısının iki katına çıkması', 'Nehirlerin kuruyup göllerin tuzlanması', 'Bölgede kar yağışının aylarca sürmesi'], 'Toplu çiçeklenme çok büyük miktarda tohum üretir; bu bolluk kemirgenlerin hızla çoğalmasına, tohum tükenince de sıçanların ekinlere yönelip kıtlığa yol açmasına neden olur.'),
  ('Gökyüzünde bazen okyanus dalgalarına benzeyen, kıvrılmış tepeli düzenli bulut sıraları görülür. Bu Kelvin-Helmholtz bulutlarını oluşturan koşul nedir?', 'Farklı hızlarda akan iki hava katmanı arasındaki sınırda dalgalanma oluşması', ['Bir volkanın küllerinin dalga biçiminde püskürmesi', 'Okyanus dalgalarının bulutlara doğrudan yansıması', 'Güneş ışığının bulutu dalga biçiminde ısıtması'], 'Üstteki hızlı hava katmanı alttakinin üzerinden kayarken sınır dalgalanır ve dalga tepeleri kıvrılır; bulut bu dalgaları görünür kılar.'),
  ('Avustralya çöllerinde yaşayan dikenli şeytan kertenkelesinin (Moloch horridus) su elde etme yöntemi hangisidir?', 'Derisindeki ince kanallarla nemli kum ve çiyden gelen suyu ağzına iletmek', ['Kaktüs gövdelerini delip özsuyunu emmek', 'Göllere inip dilini sarkıtarak su içmek', 'Yalnız yediği karıncaların vücudundaki sudan yararlanmak'], 'Pulları arasındaki kılcal kanallar suyu kılcallık etkisiyle ağız köşelerine taşır; kertenkele nemli kuma bastığında ya da çiy toplandığında bu suyu yutar.'),
  ('Sahra\'nın en sıcak saatlerinde bile yuvasından çıkıp ısıdan ölmüş böcekleri toplayan Sahra gümüş karıncasının (Cataglyphis bombycina) sıcağa karşı uyumlarından biri hangisidir?', 'Güneş ışığını yansıtan gümüşi kıllarla kaplı olması', ['Gece boyunca yuvada suda yüzerek serinlemesi', 'Kumun içinde yüzerek yalnız gölgede yürümesi', 'Siyah renkli vücuduyla ısıyı soğurup depolaması'], 'Gümüş karıncanın üçgen kesitli kılları güneş ışığını yansıtır ve vücut ısısını yayar; uzun bacakları sayesinde sıcak kumdan uzak kalır ve hızlı koşar.'),
  ('Kırmızı alglerin denizde yeşil alglerden daha derinlerde yaşayabilmesi hangi özellikleriyle açıklanır?', 'Derine en iyi ulaşan mavi-yeşil ışığı soğuran ek pigmentlere sahip olmaları', ['Fotosentez yapmadan yalnız organik madde emmeleri', 'Kalın kabuklarıyla su basıncını dengelemeleri', 'Derin sularda ışık üreten bakterilerle beslenmeleri'], 'Su kırmızı ışığı ilk birkaç metrede soğurur; kırmızı alglerdeki fikoeritrin gibi pigmentler derinlere ulaşan mavi-yeşil ışığı yakalayarak fotosentezi sürdürür.'),
  ('Bodrum ve çevresinde uzun süre önemli bir geçim kaynağı olan sünger avcılığı 1980\'lerin sonunda neden büyük ölçüde çökmüştür?', 'Doğu Akdeniz\'de yayılan bir sünger hastalığı ve aşırı toplama nedeniyle', ['Süngerlerin tamamen tatlı sulara göç etmesiyle', 'Süngerlerin zehirli hâle gelip yasaklanmasıyla', 'Süngerlerin kıyıdaki kumullara taşınmasıyla'], '1986\'dan sonra Akdeniz\'de görülen bir hastalık ticari sünger yataklarının büyük kısmını öldürdü; zaten yoğun avlanan popülasyonlar bu darbeden sonra eski düzeyine dönemedi.'),
  ('Bir avuç verimli toprakta en kalabalık hayvan gruplarından biri olan ve karın altındaki sıçrama organıyla bilinen, çoğu birkaç milimetreden küçük altı bacaklı eklembacaklılar hangileridir?', 'Kollemboller (toprak pireleri)', ['Örümcekler', 'Kırkayaklar (Diplopoda)', 'Akrepler'], 'Kollemboller mantar iplikleri ve çürüyen bitki parçalarıyla beslenir; karın altındaki çatal biçimli organı yere vurarak sıçrar ve ayrışma sürecine önemli katkı yapar.'),
];
